options.css:
:root, :host {
  --bg:#070b10;
  --bg-2:#0a1017;
  --panel:#0d131b;
  --panel-2:#111923;
  --panel-3:#151e29;

  --border:#202a35;
  --border-soft:#18212b;
  --border-bright:#2b3947;

  --text:#f1f5f9;
  --label:#c7d0da;
  --muted:#8c98a6;
  --faint:#697583;

  --cyan:#39bdf8;
  --cyan-2:#238cf0;
  --cyan-bg:rgba(57,189,248,.13);

  --ok:#2ed47a;
  --ok-bg:rgba(46,212,122,.12);

  --warn:#f5b323;
  --warn-bg:rgba(245,179,35,.12);

  --fail:#ff564f;
  --fail-bg:rgba(255,86,79,.12);

  --none:#a8b1bc;
  --none-bg:rgba(168,177,188,.09);

  --font-sans:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  --font-mono:ui-monospace,"Cascadia Code",Consolas,"SFMono-Regular",monospace;
}

* {
  box-sizing:border-box;
}

html,
body {
  margin:0;
  padding:0;
  background:var(--bg);
}

button,
input {
  font:inherit;
}

#vb-root {
  position:relative;
  isolation:isolate;
  min-height:100vh;
  padding:12px;
  display:flex;
  flex-direction:column;
  gap:8px;
  overflow:hidden;

  color:var(--text);
  font-family:var(--font-sans);

  background:
    radial-gradient(900px 420px at 50% -160px, rgba(57,189,248,.09), transparent 68%),
    radial-gradient(700px 380px at -100px 55%, rgba(35,140,240,.05), transparent 70%),
    repeating-linear-gradient(
      0deg,
      rgba(255,255,255,.010) 0,
      rgba(255,255,255,.010) 1px,
      transparent 1px,
      transparent 5px
    ),
    var(--bg);
}

#vb-root::before {
  content:"";
  position:absolute;
  inset:0;
  z-index:-1;
  pointer-events:none;
  opacity:.32;
  background:
    linear-gradient(120deg, transparent 0 44%, rgba(255,255,255,.018) 45%, transparent 46% 100%);
  background-size:160px 90px;
}

.vb-num {
  font-family:var(--font-mono);
  font-variant-numeric:tabular-nums;
}

/* =========================================================
   TOPO
   ========================================================= */

.vb-topbar {
  min-height:78px;
  display:grid;
  grid-template-columns:minmax(180px,1fr) minmax(320px,1.8fr) minmax(250px,1fr);
  align-items:center;
  gap:16px;
  padding:12px 18px;

  background:linear-gradient(180deg, rgba(13,19,27,.98), rgba(9,14,20,.98));
  border:1px solid var(--border);
  border-radius:12px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.025),
    0 10px 30px rgba(0,0,0,.18);
}

.vb-brand {
  display:flex;
  align-items:center;
  gap:11px;
  min-width:0;
}

.vb-brand-mark {
  width:42px;
  height:42px;
  flex:none;
  display:grid;
  place-items:center;
  border-radius:10px;

  color:#071117;
  background:linear-gradient(145deg, #4fd9d1, #24aeb9);
  box-shadow:
    0 0 0 1px rgba(79,217,209,.35),
    0 0 22px rgba(57,189,248,.10);
}

.vb-brand-mark svg {
  width:24px;
  height:24px;
  fill:none;
  stroke:currentColor;
  stroke-width:2.2;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.vb-brand-copy {
  min-width:0;
  display:flex;
  flex-direction:column;
  line-height:1;
}

.vb-brand-copy strong {
  color:#f8fbff;
  font-size:18px;
  font-weight:800;
  letter-spacing:.12em;
}

.vb-brand-copy span {
  margin-top:6px;
  color:var(--muted);
  font-size:10px;
  font-weight:700;
  letter-spacing:.18em;
}

.vb-page-title {
  min-width:0;
  text-align:center;
}

.vb-page-title h1 {
  margin:0;
  color:#f8fbff;
  font-size:22px;
  line-height:1.05;
  font-weight:800;
  letter-spacing:.025em;
}

.vb-page-title span {
  display:block;
  margin-top:6px;
  color:var(--muted);
  font-size:11px;
}

.vb-head-status {
  display:grid;
  grid-template-columns:auto auto;
  justify-content:end;
  align-items:center;
  gap:5px 13px;
  text-align:right;
}

.vb-verdict {
  justify-self:end;
  display:inline-flex;
  align-items:center;
  gap:7px;
  min-height:28px;
  padding:5px 10px;
  border:1px solid var(--border-bright);
  border-radius:999px;
  font-size:11px;
  font-weight:700;
}

.vb-verdict .dot {
  width:7px;
  height:7px;
  border-radius:50%;
}

.vb-verdict.ok {
  color:var(--ok);
  background:var(--ok-bg);
  border-color:rgba(46,212,122,.36);
}

.vb-verdict.ok .dot {
  background:var(--ok);
  box-shadow:0 0 10px var(--ok);
}

.vb-verdict.warn {
  color:var(--warn);
  background:var(--warn-bg);
  border-color:rgba(245,179,35,.36);
}

.vb-verdict.warn .dot {
  background:var(--warn);
  box-shadow:0 0 10px var(--warn);
}

.vb-verdict.fail {
  color:var(--fail);
  background:var(--fail-bg);
  border-color:rgba(255,86,79,.36);
}

.vb-verdict.fail .dot {
  background:var(--fail);
  box-shadow:0 0 10px var(--fail);
}

.vb-clock {
  color:#f5f8fb;
  font-size:16px;
  font-weight:750;
  letter-spacing:.06em;
}

.vb-head-meta {
  grid-column:1 / -1;
  color:var(--muted);
  font-size:10px;
  line-height:1.45;
}

.vb-head-meta b {
  color:var(--label);
  font-weight:650;
}

.vb-head-meta span {
  display:block;
}

/* =========================================================
   KPIs
   ========================================================= */

.vb-kpis {
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:8px;
  padding:8px;

  background:rgba(9,14,20,.70);
  border:1px solid var(--border);
  border-radius:12px;
}

.vb-kpi-card {
  position:relative;
  min-height:88px;
  overflow:hidden;
  display:flex;
  align-items:center;
  gap:13px;
  padding:14px 15px 16px;

  background:
    linear-gradient(110deg, rgba(255,255,255,.025), transparent 54%),
    var(--panel-2);

  border:1px solid var(--border);
  border-radius:9px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.02),
    0 8px 20px rgba(0,0,0,.12);
}

.vb-kpi-card::after {
  content:"";
  position:absolute;
  inset:auto 0 0;
  height:24px;
  pointer-events:none;
  opacity:.22;
  background:linear-gradient(0deg, currentColor, transparent);
}

.vb-kpi-icon {
  width:38px;
  height:38px;
  flex:none;
  display:grid;
  place-items:center;
  border-radius:8px;
  background:rgba(255,255,255,.055);
  color:currentColor;
}

.vb-kpi-icon svg,
.vb-section-icon svg {
  width:21px;
  height:21px;
  fill:none;
  stroke:currentColor;
  stroke-width:2;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.vb-kpi-copy {
  min-width:0;
  display:flex;
  flex-direction:column;
}

.vb-kpi-value {
  color:#f8fbff;
  font-size:20px;
  line-height:1;
  font-weight:800;
}

.vb-kpi-label {
  margin-top:6px;
  color:var(--label);
  font-size:10px;
  line-height:1.1;
  font-weight:800;
  letter-spacing:.04em;
  text-transform:uppercase;
}

.vb-kpi-copy small {
  margin-top:4px;
  overflow:hidden;
  color:var(--muted);
  font-size:9px;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-kpi-accent {
  position:absolute;
  left:0;
  right:0;
  bottom:0;
  height:2px;
  background:currentColor;
  box-shadow:0 0 14px currentColor;
}

.vb-kpi-card--cyan {
  color:var(--cyan);
}

.vb-kpi-card--green {
  color:var(--ok);
}

.vb-kpi-card--red {
  color:var(--fail);
}

.vb-kpi-card--amber {
  color:var(--warn);
}

/* =========================================================
   ÁREA PRINCIPAL
   ========================================================= */

.vb-main {
  min-height:0;
  display:grid;
  grid-template-columns:minmax(0, 1.32fr) minmax(340px, .88fr);
  gap:8px;
}

.vb-panel {
  min-width:0;
  overflow:hidden;
  background:rgba(13,19,27,.96);
  border:1px solid var(--border);
  border-radius:12px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.018),
    0 10px 28px rgba(0,0,0,.13);
}

.vb-section-head {
  min-height:58px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:10px 14px;
  border-bottom:1px solid var(--border-soft);
}

.vb-section-title {
  min-width:0;
  display:flex;
  align-items:center;
  gap:10px;
}

.vb-section-icon {
  width:30px;
  height:30px;
  flex:none;
  display:grid;
  place-items:center;
  border-radius:7px;
  color:var(--cyan);
  background:var(--cyan-bg);
  box-shadow:0 0 18px rgba(57,189,248,.08);
}

.vb-section-title h2 {
  margin:0;
  color:#f4f8fb;
  font-size:12px;
  line-height:1;
  font-weight:850;
  letter-spacing:.03em;
}

.vb-section-title small {
  display:block;
  margin-top:5px;
  color:var(--muted);
  font-size:9px;
}

/* =========================================================
   ABAS
   ========================================================= */

.vb-tabs {
  display:flex;
  flex-wrap:wrap;
  justify-content:flex-end;
  gap:5px;
}

.vb-tab {
  appearance:none;
  min-height:26px;
  display:inline-flex;
  align-items:center;
  gap:7px;
  padding:4px 8px;

  color:#8d98a5;
  background:#151c25;
  border:1px solid #26303b;
  border-radius:999px;

  font-size:9px;
  font-weight:750;
  cursor:pointer;
  outline:none;

  transition:
    color .15s ease,
    border-color .15s ease,
    background .15s ease,
    transform .15s ease,
    box-shadow .15s ease;
}

.vb-tab:hover {
  color:#dce5ec;
  border-color:#3a4653;
  transform:translateY(-1px);
}

.vb-tab b {
  min-width:17px;
  padding:1px 5px;
  border-radius:999px;
  color:inherit;
  background:rgba(255,255,255,.055);
  font-size:9px;
  text-align:center;
}

.vb-tab.is-active {
  color:#eaf8ff;
  background:linear-gradient(180deg, #35bdf2, #268fd0);
  border-color:#59c9f4;
  box-shadow:
    0 0 0 1px rgba(57,189,248,.16),
    0 0 14px rgba(57,189,248,.20);
}

.vb-tab.is-active b {
  color:#fff;
  background:rgba(5,39,56,.28);
}

/* =========================================================
   JOBS
   ========================================================= */

.vb-status-bar {
  display:flex;
  height:5px;
  overflow:hidden;
  margin:9px 14px 8px;
  background:#18212b;
  border-radius:999px;
}

.vb-status-bar > span {
  display:block;
  min-width:0;
}

.vb-status-bar .is-ok {
  background:var(--ok);
}

.vb-status-bar .is-warn {
  background:var(--warn);
}

.vb-status-bar .is-fail {
  background:var(--fail);
}

.vb-status-bar .is-none {
  background:var(--none);
}

.vb-job-table-head,
.vb-job-row {
  display:grid;
  grid-template-columns:34px minmax(180px, 1fr) 86px 112px 78px;
  align-items:center;
  gap:8px;
}

.vb-job-table-head {
  min-height:30px;
  padding:0 14px;
  color:#6f7b88;
  background:#101720;
  border-top:1px solid rgba(255,255,255,.015);
  border-bottom:1px solid var(--border-soft);
  font-size:8px;
  font-weight:800;
  letter-spacing:.045em;
  text-transform:uppercase;
}

.vb-job-table-head span:first-child {
  text-align:center;
}

.vb-job-table-head span:nth-child(4),
.vb-job-table-head span:nth-child(5) {
  text-align:right;
}

.vb-jobs-scroll,
.vb-repos-scroll {
  scrollbar-width:thin;
  scrollbar-color:#2a3642 transparent;
}

.vb-jobs-scroll {
  max-height:510px;
  overflow:auto;
}

.vb-job-row {
  min-height:48px;
  padding:7px 14px;
  border-bottom:1px solid var(--border-soft);
  transition:background .14s ease;
}

.vb-job-row:hover {
  background:rgba(57,189,248,.035);
}

.vb-status-dot {
  width:7px;
  height:7px;
  justify-self:center;
  border-radius:50%;
}

.d-ok {
  background:var(--ok);
  box-shadow:0 0 8px rgba(46,212,122,.42);
}

.d-warn {
  background:var(--warn);
  box-shadow:0 0 8px rgba(245,179,35,.38);
}

.d-fail {
  background:var(--fail);
  box-shadow:0 0 8px rgba(255,86,79,.38);
}

.d-none {
  background:var(--none);
}

.vb-job-name {
  min-width:0;
}

.vb-job-name strong {
  display:block;
  overflow:hidden;
  color:#eef3f7;
  font-size:10px;
  font-weight:750;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-job-name small {
  display:block;
  margin-top:4px;
  overflow:hidden;
  color:#6f7b88;
  font-size:8px;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-job-type,
.vb-job-age {
  overflow:hidden;
  color:#98a4af;
  font-size:9px;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-job-age {
  text-align:right;
}

.vb-chip {
  justify-self:end;
  min-width:60px;
  padding:4px 7px;
  border-radius:5px;
  font-size:8px;
  font-weight:800;
  text-align:center;
  white-space:nowrap;
}

.c-ok {
  color:var(--ok);
  background:var(--ok-bg);
}

.c-warn {
  color:var(--warn);
  background:var(--warn-bg);
}

.c-fail {
  color:var(--fail);
  background:var(--fail-bg);
}

.c-none {
  color:#c1cad3;
  background:var(--none-bg);
}

/* =========================================================
   REPOSITÓRIOS
   ========================================================= */

.vb-repo-summary {
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:7px;
  padding:10px 12px 4px;
}

.vb-repo-summary > div {
  min-width:0;
  padding:9px 10px;
  background:#111923;
  border:1px solid var(--border-soft);
  border-radius:7px;
}

.vb-repo-summary span {
  display:block;
  color:var(--muted);
  font-size:8px;
  text-transform:uppercase;
  letter-spacing:.04em;
}

.vb-repo-summary strong {
  display:block;
  margin-top:4px;
  overflow:hidden;
  color:#f4f8fb;
  font-size:12px;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-repos-scroll {
  max-height:475px;
  overflow:auto;
  padding:7px 12px 12px;
}

.vb-repo-card {
  padding:11px 0;
  border-bottom:1px solid var(--border-soft);
}

.vb-repo-card:last-child {
  border-bottom:0;
}

.vb-repo-top {
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:12px;
}

.vb-repo-top > div {
  min-width:0;
}

.vb-repo-top strong {
  display:block;
  overflow:hidden;
  color:#edf3f7;
  font-size:10px;
  font-weight:750;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-repo-top span {
  display:block;
  margin-top:4px;
  color:var(--muted);
  font-size:8px;
}

.vb-repo-top > b {
  flex:none;
  color:#dbe5ec;
  font-size:9px;
  font-weight:700;
}

.vb-repo-bar {
  height:5px;
  overflow:hidden;
  margin-top:9px;
  background:#18222d;
  border-radius:999px;
}

.vb-repo-bar > span {
  display:block;
  height:100%;
  border-radius:inherit;
}

.vb-repo-bar .is-ok {
  background:linear-gradient(90deg, #27c5c6, #43d6da);
  box-shadow:0 0 9px rgba(67,214,218,.20);
}

.vb-repo-bar .is-warn {
  background:linear-gradient(90deg, #e39b16, #f3ba28);
  box-shadow:0 0 9px rgba(243,186,40,.18);
}

.vb-repo-bar .is-fail {
  background:linear-gradient(90deg, #e54642, #ff6259);
  box-shadow:0 0 9px rgba(255,98,89,.18);
}

.vb-repo-meta {
  display:flex;
  justify-content:space-between;
  gap:12px;
  margin-top:7px;
  color:#75818d;
  font-size:8px;
}

.vb-repo-meta b {
  margin-left:3px;
  color:#aeb9c3;
  font-weight:650;
}

/* =========================================================
   RODAPÉ E ESTADOS
   ========================================================= */

.vb-footer {
  min-height:34px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:6px 12px;

  color:#81909c;
  background:rgba(9,14,20,.76);
  border:1px solid var(--border);
  border-radius:9px;
  font-size:9px;
}

.vb-collector-state {
  display:flex;
  align-items:center;
  gap:8px;
}

.vb-collector-state > span {
  width:7px;
  height:7px;
  flex:none;
  border-radius:50%;
}

.vb-collector-state.is-healthy > span {
  background:var(--ok);
  box-shadow:0 0 9px var(--ok);
}

.vb-collector-state.is-stale > span {
  background:var(--fail);
  box-shadow:0 0 9px var(--fail);
}

.vb-footer-counts {
  display:flex;
  align-items:center;
  gap:12px;
}

.vb-footer-counts span {
  display:inline-flex;
  align-items:center;
  gap:5px;
}

.vb-footer-counts i {
  width:6px;
  height:6px;
  border-radius:2px;
}

.vb-footer-counts .is-ok {
  background:var(--ok);
}

.vb-footer-counts .is-warn {
  background:var(--warn);
}

.vb-footer-counts .is-fail {
  background:var(--fail);
}

.vb-footer-counts .is-none {
  background:var(--none);
}

.vb-empty {
  display:grid;
  place-items:center;
  min-height:150px;
  padding:24px;
  color:var(--muted);
  font-size:10px;
  text-align:center;
}

/* =========================================================
   RESPONSIVO
   ========================================================= */

@media (max-width:1100px) {
  .vb-topbar {
    grid-template-columns:1fr auto;
  }

  .vb-page-title {
    grid-column:1 / -1;
    grid-row:1;
    order:-1;
  }

  .vb-brand {
    grid-row:2;
  }

  .vb-head-status {
    grid-row:2;
  }

  .vb-kpis {
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .vb-main {
    grid-template-columns:1fr;
  }
}

@media (max-width:720px) {
  #vb-root {
    padding:8px;
  }

  .vb-topbar {
    grid-template-columns:1fr;
  }

  .vb-brand,
  .vb-page-title,
  .vb-head-status {
    grid-column:1;
    grid-row:auto;
  }

  .vb-page-title {
    text-align:left;
  }

  .vb-head-status {
    justify-content:start;
    text-align:left;
  }

  .vb-verdict {
    justify-self:start;
  }

  .vb-kpis {
    grid-template-columns:1fr;
  }

  .vb-section-head {
    align-items:flex-start;
    flex-direction:column;
  }

  .vb-tabs {
    justify-content:flex-start;
  }

  .vb-job-table-head {
    display:none;
  }

  .vb-job-row {
    grid-template-columns:18px minmax(0, 1fr) auto;
  }

  .vb-job-type {
    display:none;
  }

  .vb-job-age {
    grid-column:2;
    text-align:left;
  }

  .vb-chip {
    grid-column:3;
    grid-row:1 / span 2;
  }

  .vb-footer {
    align-items:flex-start;
    flex-direction:column;
  }

  .vb-footer-counts {
    flex-wrap:wrap;
  }
}

/* =========================================================
   MODO NOC / TV — LEITURA A DISTÂNCIA EM 80% DE ZOOM
   ========================================================= */

#vb-root {
  height:100vh;
  min-height:720px;
  padding:18px;
  gap:12px;
  overflow:hidden;
}

.vb-topbar {
  min-height:104px;
  grid-template-columns:minmax(240px,1fr) minmax(420px,1.7fr) minmax(330px,1fr);
  gap:22px;
  padding:18px 24px;
  border-radius:14px;
}

.vb-brand {
  gap:15px;
}

.vb-brand-mark {
