/* =========================================================
   AGENDAMENTOS DOS JOBS — TV DO NOC
   ========================================================= */

.vb-job-controls {
  max-width:76%;
}

.vb-tabs {
  row-gap:7px;
}

.vb-job-table-head,
.vb-job-row {
  grid-template-columns:
    52px
    minmax(250px,1fr)
    minmax(185px,.72fr)
    150px
    112px;
}

.vb-job-table-head span:nth-child(3) {
  text-align:left;
}

.vb-job-name small {
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  gap:7px;
}

.vb-job-state {
  display:inline-flex;
  align-items:center;
  gap:5px;
  padding:3px 7px;
  border-radius:999px;
  font-style:normal;
  font-size:11px;
  font-weight:800;
  line-height:1;
  white-space:nowrap;
}

.vb-job-state::before {
  content:"";
  width:6px;
  height:6px;
  border-radius:50%;
  background:currentColor;
}

.vb-job-state.is-running {
  color:var(--ok);
  background:var(--ok-bg);
  box-shadow:0 0 10px rgba(46,212,122,.10);
}

.vb-job-state.is-running::before {
  animation:vbStatePulse 1.25s ease-in-out infinite;
}

.vb-job-state.is-warning {
  color:var(--warn);
  background:var(--warn-bg);
}

.vb-job-state.is-idle {
  color:#97a4b1;
  background:rgba(151,164,177,.09);
}

@keyframes vbStatePulse {
  0%,100% {
    opacity:.45;
    transform:scale(.82);
  }

  50% {
    opacity:1;
    transform:scale(1.18);
  }
}

.vb-job-next {
  min-width:0;
  display:flex;
  flex-direction:column;
  justify-content:center;
  gap:5px;
}

.vb-job-next strong {
