  color:#dce6ed;
  font-size:16px;
  line-height:1.1;
  font-weight:800;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-job-next small {
  overflow:hidden;
  color:var(--muted);
  font-size:12px;
  line-height:1.1;
  font-weight:650;
  white-space:nowrap;
  text-overflow:ellipsis;
}

.vb-job-next.is-soon strong,
.vb-job-next.is-soon small {
  color:var(--warn);
}

.vb-job-next.is-late strong,
.vb-job-next.is-late small {
  color:var(--fail);
}

.vb-job-next.is-none strong {
  color:#a5afb9;
}

.vb-job-next.is-none small {
  color:#737f8a;
}

