/*
  Remove limites antigos que faziam o menu de Jobs ter
  comportamento diferente do menu de Repositórios.
*/
.vb-job-controls {
  max-width:none;
  width:auto;
  display:contents;
}

/*
  Como os dois menus têm a mesma altura, a barra de status dos
  jobs e os cartões de capacidade começam na mesma linha.
*/
.vb-status-bar {
  margin-top:11px;
}

.vb-repo-summary {
  margin-top:0;
}

@media (max-width:1350px) {
  .vb-section-menu {
    min-height:116px;
    height:116px;
  }

  .vb-section-menu--jobs .vb-tabs {
    grid-template-columns:repeat(4, max-content);
    gap:7px;
  }

  .vb-tab {
    padding-left:10px;
    padding-right:10px;
  }
}

@media (max-width:1050px) {
  .vb-section-menu {
    height:auto;
    min-height:116px;
  }

  .vb-section-menu--jobs {
    align-items:stretch;
    flex-direction:column;
  }

  .vb-section-menu--jobs .vb-tabs {
    width:100%;
    grid-template-columns:repeat(4, max-content);
  }

  .vb-section-menu--jobs .vb-auto-pager {
    align-self:flex-end;
  }
}
/* =========================================================
   PAGINAÇÃO DOS REPOSITÓRIOS CENTRALIZADA
   ========================================================= */

.vb-section-menu--repos {
  justify-content:center;
}

.vb-section-menu--repos .vb-auto-pager,
.vb-section-menu--repos .vb-repo-page-single {
  margin-left:auto;
  margin-right:auto;
}
/* =========================================================
   TEMA VERDE — APENAS CORES DE FUNDO, ÍCONES E MENUS
   Referência visual:
   fundo #050c0b | painéis #0b1715 / #0f1f1b
   verde principal #32ce7e
   ========================================================= */

:root,
:host {
  --bg:#050c0b;
  --bg-2:#07120f;
  --panel:#0b1715;
  --panel-2:#0f1f1b;
  --panel-3:#13281f;

  --border:#1c362e;
  --border-soft:#112a21;
  --border-bright:#285443;

  --label:#c8d8d2;
  --muted:#829b92;
  --faint:#587168;

  /*
    O antigo ciano passa a usar o verde do dashboard
    de referência. Cores de falha e aviso são preservadas.
  */
  --cyan:#32ce7e;
  --cyan-2:#1fae68;
  --cyan-bg:rgba(50,206,126,.13);

  --ok:#32ce7e;
  --ok-bg:rgba(50,206,126,.12);
}

/* FUNDO PRINCIPAL */

html,
body {
  background:#050c0b;
}

#vb-root {
  background:
    radial-gradient(
      920px 430px at 50% -170px,
      rgba(50,206,126,.075),
      transparent 68%
    ),
    radial-gradient(
      720px 390px at -110px 55%,
      rgba(31,174,104,.045),
      transparent 70%
    ),
    repeating-linear-gradient(
      0deg,
      rgba(255,255,255,.008) 0,
      rgba(255,255,255,.008) 1px,
      transparent 1px,
      transparent 5px
    ),
    #050c0b;
}

#vb-root::before {
  opacity:.25;
  background:
    linear-gradient(
      120deg,
      transparent 0 44%,
      rgba(50,206,126,.018) 45%,
      transparent 46% 100%
    );
  background-size:160px 90px;
}

/* SUPERFÍCIES E PAINÉIS */

.vb-topbar {
  background:
    linear-gradient(
      180deg,
      rgba(11,23,21,.99),
      rgba(7,18,15,.99)
    );
  border-color:#1c4234;
}

.vb-kpis {
  background:rgba(7,18,15,.82);
  border-color:#1c4234;
}

.vb-kpi-card {
  background:
    linear-gradient(
      110deg,
      rgba(50,206,126,.025),
      transparent 54%
    ),
    #0f1f1b;
  border-color:#1c3b30;
}

.vb-panel {
  background:rgba(11,23,21,.97);
  border-color:#1c4234;
}

.vb-footer {
  background:rgba(7,18,15,.88);
  border-color:#1c4234;
}

.vb-repo-summary > div {
  background:#0f211b;
  border-color:#17392d;
}

.vb-job-table-head {
  background:#0c1a16;
}

.vb-status-bar,
.vb-repo-bar {
  background:#132b23;
}

/* ÍCONES */

.vb-brand-mark {
  color:#04110b;
  background:
    linear-gradient(
      145deg,
      #48e399,
      #28c879
    );
  box-shadow:
    0 0 0 1px rgba(72,227,153,.40),
    0 0 24px rgba(50,206,126,.18);
}

.vb-kpi-icon,
.vb-section-icon {
  color:#32ce7e !important;
  background:rgba(50,206,126,.105);
  border:1px solid rgba(50,206,126,.18);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.025),
    0 0 18px rgba(50,206,126,.06);
}

/*
  Os ícones ficam verdes, mas as barras inferiores dos KPIs
  continuam respeitando seus estados originais.
*/
.vb-kpi-card--cyan .vb-kpi-icon,
.vb-kpi-card--green .vb-kpi-icon,
.vb-kpi-card--red .vb-kpi-icon,
.vb-kpi-card--amber .vb-kpi-icon {
  color:#32ce7e !important;
}

/* MENUS E ABAS */

.vb-section-menu {
  background:
    linear-gradient(
      180deg,
      rgba(50,206,126,.028),
      rgba(50,206,126,.006)
    );
  border-color:#15382c;
}

.vb-tab {
  color:#91aaa1;
  background:#10231d;
  border-color:#25463a;
}

.vb-tab:hover {
  color:#e7fff5;
  background:#153329;
  border-color:#32ce7e;
}

.vb-tab b {
  background:rgba(50,206,126,.075);
}

.vb-tab.is-active {
  color:#04150d;
  background:
    linear-gradient(
      180deg,
      #43e493,
      #2fc878
    );
  border-color:#65eeaa;
  box-shadow:
    0 0 0 1px rgba(50,206,126,.18),
    0 0 16px rgba(50,206,126,.24);
}

.vb-tab.is-active b {
  color:#062016;
  background:rgba(0,0,0,.14);
}

.vb-page-button {
  color:#c7f7df;
  background:#10231d;
  border-color:#2a5041;
}

.vb-page-button:hover {
  color:#ffffff;
  background:#17372d;
  border-color:#32ce7e;
}

.vb-rotation-track {
  background:#163228;
}

.vb-rotation-progress {
  background:
    linear-gradient(
      90deg,
      #1fae68,
      #43e493
    );
}

/* BORDAS DOS CABEÇALHOS DOS MENUS */

.vb-section-head,
.vb-section-head--jobs,
.vb-section-head--repos {
  border-bottom-color:#15382c;
}

/* REALCE VERDE SUAVE NAS LINHAS */

.vb-job-row:hover {
  background:rgba(50,206,126,.035);
}

/* =========================================================
   AJUSTE TV/NOC — MAIS CONTEÚDO E CAIXA ALTA
   ========================================================= */

/*
  Todo o conteúdo visível fica em caixa alta sem alterar os valores
  reais retornados pelo Prometheus nem os identificadores dos jobs.
*/
#vb-root {
  text-transform:uppercase;
}

/*
  A lista passa a usar a altura restante do painel de forma uniforme.
  A paginação adaptativa usa de 4 a 8 jobs por página e ocupa melhor
  a área inferior que ficava vazia na TV.
*/
.vb-jobs-page {
  flex:1 1 auto;
  min-height:0;
  display:flex;
  flex-direction:column;
  overflow:hidden;
}

.vb-job-row {
  flex:1 1 0;
  min-height:60px !important;
  max-height:100px;
  padding-top:8px;
  padding-bottom:8px;
}

.vb-repos-page {
  flex:1 1 auto;
  min-height:0;
  display:flex;
  flex-direction:column;
  overflow:hidden;
}

.vb-repo-card {
  flex:1 1 0;
  min-height:92px !important;
  max-height:138px;
  padding-top:12px;
  padding-bottom:12px;
}

.vb-empty {
  flex:1 1 auto;
}

@media (max-height:900px) {
  .vb-job-row {
    min-height:58px !important;
    max-height:74px;
  }

  .vb-repo-card {
    min-height:88px !important;
    max-height:122px;
  }
}


/* =========================================================
