options.onRender:
/*
  VEEAM BACKUP OVERVIEW — DADOS REAIS DO PROMETHEUS

  Configure no próprio painel HTML Graphics, usando o datasource Prometheus:

  A = veeam_job_last_result
  B = veeam_job_last_run_timestamp_seconds
  C = veeam_repository_capacity_bytes
  D = veeam_repository_free_bytes
  E = veeam_collector_success
  F = veeam_collector_last_run_timestamp_seconds
  G = veeam_collector_duration_seconds
  H = veeam_job_next_run_timestamp_seconds
  I = veeam_job_state_info

  Em todas as queries:
  - Type: Instant
  - Format: Time series

  O coletor atual NÃO exporta bytes transferidos nem duração individual por job.
  Esta versão usa dados reais de agendamento:
  - o 3º KPI exibe jobs com execução prevista nas próximas 2 horas;
  - a tabela mostra a próxima e a última execução;
  - as abas permitem filtrar jobs agendados e sem agendamento;
  - a paginação se adapta à altura da TV para exibir mais jobs;
  - o estado atual retornado pela API aparece abaixo do nome do job.
*/

const root = htmlNode.querySelector("#vb-root");

if (!root) {
  throw new Error('Elemento "#vb-root" não encontrado no HTML.');
}

const SERIES = (
  typeof data !== "undefined" &&
  data &&
  Array.isArray(data.series)
)
  ? data.series
  : [];

const DEMO_LOGO_DATA = "data:image/svg+xml;base64,";

const METRICS = {
  jobResult: {
    refId: "A",
    name: "veeam_job_last_result"
  },
  jobLastRun: {
    refId: "B",
    name: "veeam_job_last_run_timestamp_seconds"
  },
  repoCapacity: {
    refId: "C",
    name: "veeam_repository_capacity_bytes"
  },
  repoFree: {
    refId: "D",
    name: "veeam_repository_free_bytes"
  },
  collectorSuccess: {
    refId: "E",
    name: "veeam_collector_success"
  },
  collectorLastRun: {
    refId: "F",
    name: "veeam_collector_last_run_timestamp_seconds"
  },
  collectorDuration: {
    refId: "G",
    name: "veeam_collector_duration_seconds"
  },
  jobNextRun: {
    refId: "H",
    name: "veeam_job_next_run_timestamp_seconds"
  },
  jobState: {
    refId: "I",
    name: "veeam_job_state_info"
  }
};

const RESULT = {
  0: ["Sucesso", "ok"],
  1: ["Aviso", "warn"],
  2: ["Falha", "fail"],
  3: ["Sem dados", "none"]
};

const now = () => Math.floor(Date.now() / 1000);

/* =========================================================
   LEITURA DOS DATA FRAMES DO GRAFANA
   ========================================================= */

function valuesToArray(values) {
  if (!values) {
    return [];
  }

  if (Array.isArray(values)) {
    return values;
  }

  if (typeof values.toArray === "function") {
    return values.toArray();
  }

  if (
    typeof values.length === "number" &&
    typeof values.get === "function"
  ) {
    const result = [];

    for (let index = 0; index < values.length; index++) {
      result.push(values.get(index));
    }

    return result;
  }

  if (values.buffer !== undefined && values.buffer !== null) {
    try {
      return Array.from(values.buffer);
    } catch (error) {
      return [];
    }
  }

  return [];
}

function getValueField(frame) {
  if (!frame || !Array.isArray(frame.fields)) {
    return null;
  }

  let fallback = null;

  for (const field of frame.fields) {
    const fieldName = String(field.name || "").toLowerCase();

    if (fieldName === "time") {
      continue;
    }

    if (field.type === "number") {
      return field;
    }

    if (!fallback) {
      fallback = field;
    }
  }

  return fallback;
}

function getLastNumericValue(frame) {
  const field = getValueField(frame);

  if (!field) {
    return null;
  }

  const values = valuesToArray(field.values);

  for (let index = values.length - 1; index >= 0; index--) {
    const numericValue = Number(values[index]);

    if (Number.isFinite(numericValue)) {
      return numericValue;
    }
  }

  if (field.state && field.state.calcs) {
    const lastNotNull = Number(field.state.calcs.lastNotNull);

    if (Number.isFinite(lastNotNull)) {
      return lastNotNull;
    }

    const last = Number(field.state.calcs.last);

    if (Number.isFinite(last)) {
      return last;
    }
  }

  return null;
}

function mergeLabels(target, source) {
  if (!source) {
    return target;
  }

  Object.keys(source).forEach((key) => {
    target[key] = source[key];
  });

  return target;
}

function parseLabelsFromText(text) {
  const labels = {};

  if (!text) {
    return labels;
  }

  const source = String(text);
  const regex = /([a-zA-Z_][a-zA-Z0-9_]*)="((?:\\.|[^"])*)"/g;
  let match;

  while ((match = regex.exec(source)) !== null) {
    labels[match[1]] = match[2]
      .replace(/\\"/g, '"')
      .replace(/\\\\/g, "\\");
  }

  return labels;
}

function getFrameLabels(frame) {
  const labels = {};
  const field = getValueField(frame);

  if (frame && frame.labels) {
    mergeLabels(labels, frame.labels);
  }

  if (field && field.labels) {
    mergeLabels(labels, field.labels);
  }

  if (frame && frame.name) {
    mergeLabels(labels, parseLabelsFromText(frame.name));
  }

  if (
    field &&
    field.config &&
    field.config.displayNameFromDS
  ) {
    mergeLabels(
      labels,
      parseLabelsFromText(field.config.displayNameFromDS)
    );
  }

  if (
    field &&
    field.config &&
    field.config.displayName
  ) {
    mergeLabels(
      labels,
      parseLabelsFromText(field.config.displayName)
    );
  }

  return labels;
}

function frameContainsMetric(frame, metricName) {
  const field = getValueField(frame);
  const labels = getFrameLabels(frame);

  if (labels.__name__ === metricName) {
    return true;
  }

  const candidates = [
    frame ? frame.name : "",
    field ? field.name : "",
    field && field.config ? field.config.displayName : "",
    field && field.config ? field.config.displayNameFromDS : ""
  ];

  return candidates.some((candidate) =>
    String(candidate || "").indexOf(metricName) !== -1
  );
}

function getMetricFrames(metric) {
  const byRefId = SERIES.filter(
    (frame) => String(frame.refId || "") === metric.refId
  );

  if (byRefId.length > 0) {
    return byRefId;
  }

  return SERIES.filter(
    (frame) => frameContainsMetric(frame, metric.name)
  );
}

function getScalarMetric(metric, fallbackValue) {
  const frames = getMetricFrames(metric);

  for (const frame of frames) {
    const value = getLastNumericValue(frame);

    if (value !== null && Number.isFinite(value)) {
      return value;
    }
  }

  return fallbackValue;
}

/* =========================================================
   MONTA O OBJETO NO MESMO FORMATO DO MOCK ORIGINAL
   ========================================================= */

function buildRealData() {
  const jobsByName = new Map();
  const reposByName = new Map();

  function getJob(jobName) {
    if (!jobsByName.has(jobName)) {
      jobsByName.set(jobName, {
        name: jobName,
        type: "Backup",
        result: 3,
        lastRunTs: 0,
        nextRunTs: 0,
        state: "unknown"
      });
    }

    return jobsByName.get(jobName);
  }

  function getRepo(repoName) {
    if (!reposByName.has(repoName)) {
      reposByName.set(repoName, {
        name: repoName,
        capacityBytes: 0,
        freeBytes: 0
      });
    }

    return reposByName.get(repoName);
  }

  /* A — resultado do último job */

  getMetricFrames(METRICS.jobResult).forEach((frame) => {
    const labels = getFrameLabels(frame);
    const value = getLastNumericValue(frame);
    const jobName = labels.job_name;

    if (!jobName || value === null || !Number.isFinite(value)) {
      return;
    }

    const job = getJob(jobName);
    const result = Number(value);

    job.result = [0, 1, 2, 3].includes(result)
      ? result
      : 3;

    job.type = labels.job_type || job.type;
  });

  /* B — timestamp da última execução */

  getMetricFrames(METRICS.jobLastRun).forEach((frame) => {
    const labels = getFrameLabels(frame);
    const value = getLastNumericValue(frame);
    const jobName = labels.job_name;

    if (!jobName || value === null || !Number.isFinite(value)) {
      return;
    }

    const job = getJob(jobName);
    job.lastRunTs = Number(value);
    job.type = labels.job_type || job.type;
  });

  /* H — timestamp da próxima execução */

  getMetricFrames(METRICS.jobNextRun).forEach((frame) => {
    const labels = getFrameLabels(frame);
    const value = getLastNumericValue(frame);
    const jobName = labels.job_name;

    if (!jobName || value === null || !Number.isFinite(value)) {
      return;
    }

    const job = getJob(jobName);
    job.nextRunTs = Number(value);
    job.type = labels.job_type || job.type;
  });

  /* I — estado atual retornado pela API */

  getMetricFrames(METRICS.jobState).forEach((frame) => {
    const labels = getFrameLabels(frame);
    const value = getLastNumericValue(frame);
    const jobName = labels.job_name;

    if (
      !jobName ||
      value === null ||
      !Number.isFinite(value) ||
      Number(value) !== 1
    ) {
      return;
    }

    const job = getJob(jobName);
    job.state = labels.state || "unknown";
    job.type = labels.job_type || job.type;
  });

  /* C — capacidade do repositório */

  getMetricFrames(METRICS.repoCapacity).forEach((frame) => {
    const labels = getFrameLabels(frame);
    const value = getLastNumericValue(frame);
    const repoName = labels.repository;

    if (!repoName || value === null || !Number.isFinite(value)) {
      return;
    }

    getRepo(repoName).capacityBytes = Number(value);
  });

  /* D — espaço livre do repositório */

  getMetricFrames(METRICS.repoFree).forEach((frame) => {
    const labels = getFrameLabels(frame);
    const value = getLastNumericValue(frame);
    const repoName = labels.repository;

    if (!repoName || value === null || !Number.isFinite(value)) {
      return;
    }

    getRepo(repoName).freeBytes = Number(value);
  });

  const jobs = Array.from(jobsByName.values());

  const repos = Array.from(reposByName.values())
    .filter((repo) => Number(repo.capacityBytes) > 0);

  return {
    jobs,
    repos,
    collector: {
      success: Number(
        getScalarMetric(METRICS.collectorSuccess, 0)
      ),
      lastRunTs: Number(
        getScalarMetric(METRICS.collectorLastRun, 0)
      ),
      durationSec: Number(
        getScalarMetric(METRICS.collectorDuration, 0)
      )
    }
  };
}

/* =========================================================
   FORMATAÇÃO
   ========================================================= */

function escapeHtml(value) {
  return String(
    value === null || value === undefined ? "" : value
  )
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function fmtBytes(bytes) {
  const value = Number(bytes);

  if (!Number.isFinite(value) || value <= 0) {
    return "0 B";
  }

  const units = ["B", "KB", "MB", "GB", "TB", "PB"];
  const base = 1024;

  let index = Math.floor(
    Math.log(value) / Math.log(base)
  );

  index = Math.max(
    0,
    Math.min(index, units.length - 1)
  );

  const converted = value / Math.pow(base, index);
  const decimals = index >= 3 ? 1 : 0;

  return converted.toFixed(decimals) + " " + units[index];
}

function fmtAge(timestamp) {
  const ts = Number(timestamp);

  if (!Number.isFinite(ts) || ts <= 0) {
    return "nunca";
  }

  const seconds = Math.max(0, now() - ts);

  if (seconds < 60) {
    return "Há " + seconds + "s";
  }

  if (seconds < 3600) {
    return "Há " + Math.floor(seconds / 60) + " min";
  }

  if (seconds < 86400) {
    return "Há " + Math.floor(seconds / 3600) + " h";
  }

  return "há " + Math.floor(seconds / 86400) + " d";
}

function fmtUntil(timestamp) {
  const ts = Number(timestamp);

  if (!Number.isFinite(ts) || ts <= 0) {
    return "sem horário";
  }

  const seconds = ts - now();

  if (seconds <= 0) {
    const lateSeconds = Math.abs(seconds);

    if (lateSeconds < 3600) {
      return "horário passou há " +
        Math.max(1, Math.floor(lateSeconds / 60)) +
        " min";
    }

    return "horário já passou";
  }

  if (seconds < 3600) {
    return "em " +
      Math.max(1, Math.ceil(seconds / 60)) +
      " min";
  }

  if (seconds < 86400) {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);

    return minutes > 0
      ? "em " + hours + "h " + minutes + "min"
      : "em " + hours + "h";
  }

  return "em " + Math.floor(seconds / 86400) + " d";
}

function fmtNextRun(timestamp) {
  const ts = Number(timestamp);

  if (!Number.isFinite(ts) || ts <= 0) {
    return {
      main: "Sem agendamento",
      detail: "execução manual ou não programada",
      tone: "none"
    };
  }

  const date = new Date(ts * 1000);
  const currentDate = new Date();
  const tomorrow = new Date();

  tomorrow.setDate(currentDate.getDate() + 1);

  const sameDay = (
    date.getFullYear() === currentDate.getFullYear() &&
    date.getMonth() === currentDate.getMonth() &&
    date.getDate() === currentDate.getDate()
  );

  const isTomorrow = (
    date.getFullYear() === tomorrow.getFullYear() &&
    date.getMonth() === tomorrow.getMonth() &&
    date.getDate() === tomorrow.getDate()
  );

  const timeText = date.toLocaleTimeString(
    "pt-BR",
    {
      hour: "2-digit",
      minute: "2-digit"
    }
  );

  let dateText;

  if (sameDay) {
    dateText = "Hoje às " + timeText;
  } else if (isTomorrow) {
    dateText = "Amanhã às " + timeText;
  } else {
    dateText = date.toLocaleDateString(
      "pt-BR",
      {
        day: "2-digit",
        month: "2-digit"
      }
    ) + " às " + timeText;
  }

  const secondsUntil = ts - now();

  return {
    main: dateText,
    detail: fmtUntil(ts),
    tone:
      secondsUntil > 0 && secondsUntil <= 7200
        ? "soon"
        : secondsUntil <= 0
          ? "late"
          : "scheduled"
  };
}

function translateJobState(state) {
  const normalized = String(state || "unknown")
    .trim()
    .toLowerCase();

  const states = {
    inactive: "Parado",
    stopped: "Parado",
    running: "Em execução",
    working: "Em execução",
    starting: "Iniciando",
    stopping: "Finalizando",
    paused: "Pausado",
    disabling: "Desabilitando",
    disabled: "Desabilitado",
    enabled: "Habilitado",
    unknown: "Estado não informado"
  };

  if (states[normalized]) {
    return states[normalized];
  }

  return normalized
    .replace(/_/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function jobStateClass(state) {
  const normalized = String(state || "").toLowerCase();

  if (
    normalized === "running" ||
    normalized === "working" ||
    normalized === "starting"
  ) {
    return "is-running";
  }

  if (
    normalized === "stopping" ||
    normalized === "paused"
  ) {
    return "is-warning";
  }

  return "is-idle";
}

function fmtCollectorDuration(seconds) {
  const value = Number(seconds);

  if (!Number.isFinite(value) || value < 0) {
    return "-";
  }

  if (value < 1) {
    return Math.round(value * 1000) + " ms";
  }

  if (value < 60) {
    return value.toFixed(value < 10 ? 1 : 0) + " s";
  }

  const minutes = Math.floor(value / 60);
  const remainingSeconds = Math.floor(value % 60);

  return minutes + "m " + remainingSeconds + "s";
}

function el(tag, cls, html) {
  const element = document.createElement(tag);

  if (cls) {
    element.className = cls;
  }

  if (html !== null && html !== undefined) {
    element.innerHTML = html;
  }

  return element;
}

function effectiveResult(job) {
  if (!Number(job.lastRunTs)) {
    return 3;
  }

  const result = Number(job.result);

  return [0, 1, 2, 3].includes(result)
    ? result
    : 3;
}


function jobMatchesFilter(job, filterName) {
  const status = effectiveResult(job);

  if (filterName === "with-data") {
    return status !== 3;
  }

  if (filterName === "success") {
    return status === 0;
  }

  if (filterName === "warning") {
    return status === 1;
  }

  if (filterName === "failed") {
    return status === 2;
  }

  if (filterName === "no-data") {
    return status === 3;
  }

  if (filterName === "scheduled") {
    return Number(job.nextRunTs) > 0;
  }

  if (filterName === "unscheduled") {
    return !Number(job.nextRunTs);
  }

  return true;
}

/* =========================================================
   RENDERIZAÇÃO — MESMO LAYOUT DO ORIGINAL
   ========================================================= */

function iconSvg(name) {
  const icons = {
    shield: `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M12 3 19 6v5c0 4.6-2.7 8.2-7 10-4.3-1.8-7-5.4-7-10V6l7-3Z"></path>
        <path d="m9 12 2 2 4-5"></path>
      </svg>
    `,
    jobs: `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <rect x="4" y="5" width="16" height="5" rx="2"></rect>
        <rect x="4" y="14" width="16" height="5" rx="2"></rect>
        <path d="M8 8h.01M8 17h.01"></path>
      </svg>
    `,
    clock: `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <circle cx="12" cy="12" r="9"></circle>
        <path d="M12 7v5l3 2"></path>
      </svg>
    `,
    storage: `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <ellipse cx="12" cy="6" rx="8" ry="3"></ellipse>
        <path d="M4 6v6c0 1.7 3.6 3 8 3s8-1.3 8-3V6"></path>
        <path d="M4 12v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6"></path>
      </svg>
    `,
    list: `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M9 6h11M9 12h11M9 18h11"></path>
        <path d="M4 6h.01M4 12h.01M4 18h.01"></path>
      </svg>
    `
  };

  return icons[name] || icons.jobs;
}

function startClock() {
  if (root.__vbClockTimer) {
    clearInterval(root.__vbClockTimer);
  }

  const updateClock = () => {
    const clockNode = root.querySelector("[data-vb-clock]");

    if (!clockNode) {
      return;
    }

    clockNode.textContent = new Date().toLocaleTimeString(
      "pt-BR",
      {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit"
      }
    );
  };

  updateClock();
  root.__vbClockTimer = setInterval(updateClock, 1000);
}

function stopDashboardRotation() {
  if (root.__vbRotationTimer) {
    clearInterval(root.__vbRotationTimer);
    root.__vbRotationTimer = null;
  }

  /*
    Limpa também nomes de timers usados em versões anteriores
    do painel, evitando rotação duplicada após uma atualização.
  */
  if (root.__vbJobsTimer) {
    clearInterval(root.__vbJobsTimer);
    root.__vbJobsTimer = null;
  }

  if (root.__vbReposTimer) {
    clearInterval(root.__vbReposTimer);
    root.__vbReposTimer = null;
  }
}

function calculateJobsPerPage() {
  /*
    TV/NOC: prioriza menos páginas e evita uma última página com
    apenas um job. Em 1080p, oito linhas cabem com boa leitura.
  */
  const availableHeight = Number(root.clientHeight || 0);

  if (availableHeight >= 1000) {
    return 8;
  }

  if (availableHeight >= 900) {
    return 7;
  }

  if (availableHeight >= 800) {
    return 6;
  }

  return 5;
}
function calculateReposPerPage() {
  /*
    A quantidade de repositórios também acompanha a altura disponível,
    diminuindo a rotação de páginas sem perder os detalhes de capacidade.
  */
  const availableHeight = Number(root.clientHeight || 0);

  if (availableHeight >= 1250) {
    return 5;
  }

  if (availableHeight >= 1080) {
    return 4;
  }

  if (availableHeight >= 930) {
    return 3;
  }

  return 2;
}

function startDashboardRotation(
  d,
  totalJobPages,
  totalRepoPages
) {
  stopDashboardRotation();

  if (totalJobPages <= 1 && totalRepoPages <= 1) {
    return;
  }

  root.__vbRotationTimer = setInterval(() => {
    if (totalJobPages > 1) {
      const currentJobPage = Number(
        root.dataset.vbJobPage || 0
      );

      root.dataset.vbJobPage = String(
        (currentJobPage + 1) % totalJobPages
      );
    }

    if (totalRepoPages > 1) {
      const currentRepoPage = Number(
        root.dataset.vbRepoPage || 0
      );

      root.dataset.vbRepoPage = String(
        (currentRepoPage + 1) % totalRepoPages
      );
    }

    render(d);
  }, 10000);
}

function render(d) {
  stopDashboardRotation();
  root.innerHTML = "";

  const jobs = Array.isArray(d.jobs) ? d.jobs : [];
  const repos = Array.isArray(d.repos) ? d.repos : [];
  const collector = d.collector || {};

  const total = jobs.length;

  const ok = jobs.filter(
    (job) => effectiveResult(job) === 0
  ).length;

  const warn = jobs.filter(
    (job) => effectiveResult(job) === 1
  ).length;

  const fail = jobs.filter(
    (job) => effectiveResult(job) === 2
  ).length;

  const none = jobs.filter(
    (job) => effectiveResult(job) === 3
  ).length;

  const withData = total - none;

  const scheduledJobs = jobs.filter(
    (job) => Number(job.nextRunTs) > 0
  );

  const scheduled = scheduledJobs.length;
  const unscheduled = total - scheduled;

  const scheduledOk = scheduledJobs.filter(
    (job) => effectiveResult(job) === 0
  ).length;

  const upcomingTwoHours = jobs.filter((job) => {
    const nextRun = Number(job.nextRunTs);

    return (
      Number.isFinite(nextRun) &&
      nextRun > now() &&
      nextRun <= now() + 7200
    );
  }).length;

  /*
    A taxa considera somente jobs que possuem próxima execução.
    Falhas sem agendamento continuam contando para o alerta
    superior, porque o verdict usa a variável global "fail".
  */
  const rate = scheduled
    ? Math.round((scheduledOk / scheduled) * 100)
    : 0;

  const oldest = jobs.reduce((oldestTimestamp, job) => {
    const timestamp = Number(job.lastRunTs);

    if (
      timestamp > 0 &&
      (
        !oldestTimestamp ||
        timestamp < oldestTimestamp
      )
    ) {
      return timestamp;
    }

    return oldestTimestamp;
  }, 0);

  const collectorStale =
    Number(collector.success) !== 1 ||
    !Number(collector.lastRunTs) ||
    now() - Number(collector.lastRunTs) > 1800;

  const verdict =
    collectorStale
      ? ["fail", "Coletor indisponível"]
      : fail > 0
        ? ["fail", "Atenção"]
        : warn > 0 || none > 0
          ? ["warn", "Avisos"]
          : ["ok", "Saudável"];

  const repositoryUsage = repos.map((repo) => {
    const capacity = Number(repo.capacityBytes);
    const free = Number(repo.freeBytes);

    if (!capacity || capacity <= 0) {
      return 0;
    }

    return Math.max(
      0,
      Math.min(
        100,
        (1 - free / capacity) * 100
      )
    );
  });

  const fullestRepository = repositoryUsage.length
    ? Math.max.apply(null, repositoryUsage)
    : 0;

  const totalCapacity = repos.reduce(
    (sum, repo) => sum + Number(repo.capacityBytes || 0),
    0
  );

  const totalFree = repos.reduce(
    (sum, repo) => sum + Number(repo.freeBytes || 0),
    0
  );

  /* CABEÇALHO */

  const header = el("header", "vb-topbar");

  header.innerHTML = `
    <div class="vb-brand">
      <div class="vb-brand-mark">
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M4 7l8 11 8-11"></path>
          <path d="M8 4h8"></path>
        </svg>
      </div>

      <div class="vb-brand-copy">
        <strong>VEEAM</strong>
        <span>DEMO-PA</span>
      </div>
    </div>

    <div class="vb-demo-center">
      <img
        class="vb-demo-logo"
        src="${DEMO_LOGO_DATA}"
        alt="Demo Company - Demo Company"
      >

      <span class="vb-demo-caption">
        BACKUP OVERVIEW · MONITORAMENTO DE BACKUP
      </span>
    </div>

    <div class="vb-head-status">
      <div class="vb-verdict ${verdict[0]}">
        <span class="dot"></span>
        ${verdict[1]}
      </div>

      <div class="vb-head-meta">
        Atualizado <b>${fmtAge(collector.lastRunTs)}</b>
        <span>Backup mais antigo ${fmtAge(oldest)}</span>
      </div>
    </div>
  `;

  root.appendChild(header);

  /* KPIs */

  const kpis = el("section", "vb-kpis");

  kpis.innerHTML = `
    <article class="vb-kpi-card vb-kpi-card--cyan">
      <div class="vb-kpi-icon">
        ${iconSvg("shield")}
      </div>

      <div class="vb-kpi-copy">
        <strong class="vb-kpi-value vb-num">${rate}%</strong>
        <span class="vb-kpi-label">Taxa de sucesso</span>
        <small>
          ${scheduledOk} de ${scheduled} jobs agendados no verde
        </small>
      </div>

      <span class="vb-kpi-accent"></span>
    </article>

    <article class="vb-kpi-card vb-kpi-card--green">
      <div class="vb-kpi-icon">
        ${iconSvg("jobs")}
      </div>

      <div class="vb-kpi-copy">
        <strong class="vb-kpi-value vb-num">${total}</strong>
        <span class="vb-kpi-label">Jobs monitorados</span>
        <small>${withData} com dados · ${none} sem dados</small>
      </div>

      <span class="vb-kpi-accent"></span>
    </article>

    <article class="vb-kpi-card vb-kpi-card--red">
      <div class="vb-kpi-icon">
        ${iconSvg("clock")}
      </div>

      <div class="vb-kpi-copy">
        <strong class="vb-kpi-value vb-num">
          ${upcomingTwoHours}
        </strong>
        <span class="vb-kpi-label">Próximos em 2 horas</span>
        <small>
          ${scheduled} agendados · ${unscheduled} sem agenda
        </small>
      </div>

      <span class="vb-kpi-accent"></span>
    </article>

    <article class="vb-kpi-card vb-kpi-card--amber">
      <div class="vb-kpi-icon">
        ${iconSvg("storage")}
      </div>

      <div class="vb-kpi-copy">
        <strong class="vb-kpi-value vb-num">
          ${fullestRepository.toFixed(0)}%
        </strong>
        <span class="vb-kpi-label">Repositório mais cheio</span>
        <small>${repos.length} repositórios monitorados</small>
      </div>

      <span class="vb-kpi-accent"></span>
    </article>
  `;

  root.appendChild(kpis);

  /* CONTEÚDO PRINCIPAL */

  const main = el("main", "vb-main");

  /* JOBS */

  const jobsPanel = el("section", "vb-panel vb-panel--jobs");

  const currentJobFilter =
    root.dataset.vbJobFilter || "with-data";

  root.dataset.vbJobFilter = currentJobFilter;

  const filteredJobs = jobs.filter(
    (job) => jobMatchesFilter(job, currentJobFilter)
  );

  const severity = {
    2: 4,
    1: 3,
    3: 2,
    0: 1
  };

  const sortedFilteredJobs = filteredJobs
    .slice()
    .sort((jobA, jobB) => {
      if (currentJobFilter === "scheduled") {
        const nextA = Number(jobA.nextRunTs || 0);
        const nextB = Number(jobB.nextRunTs || 0);

        if (nextA !== nextB) {
          return nextA - nextB;
        }

        return String(jobA.name).localeCompare(
          String(jobB.name),
          "pt-BR"
        );
      }

      if (currentJobFilter === "unscheduled") {
        return String(jobA.name).localeCompare(
          String(jobB.name),
          "pt-BR"
        );
      }

      const resultA = effectiveResult(jobA);
      const resultB = effectiveResult(jobB);

      const statusDifference =
        (severity[resultB] || 0) -
        (severity[resultA] || 0);

      if (statusDifference !== 0) {
        return statusDifference;
      }

      const timeA = Number(jobA.lastRunTs || 0);
      const timeB = Number(jobB.lastRunTs || 0);

      if (timeA !== timeB) {
        return timeA - timeB;
      }

      return String(jobA.name).localeCompare(
        String(jobB.name),
        "pt-BR"
      );
    });

  const jobsPerPage = calculateJobsPerPage();
  const totalJobPages = Math.max(
    1,
    Math.ceil(sortedFilteredJobs.length / jobsPerPage)
  );

  let currentJobPage = Number(
    root.dataset.vbJobPage || 0
  );

  if (!Number.isFinite(currentJobPage) || currentJobPage < 0) {
    currentJobPage = 0;
  }

  if (currentJobPage >= totalJobPages) {
    currentJobPage = 0;
  }

  root.dataset.vbJobPage = String(currentJobPage);

  const pageStart = currentJobPage * jobsPerPage;
  const pagedJobs = sortedFilteredJobs.slice(
    pageStart,
    pageStart + jobsPerPage
  );

  function renderTab(filterName, label, count, tone) {
    const active = currentJobFilter === filterName;

    return `
      <button
        type="button"
        class="vb-tab ${active ? "is-active" : ""}"
        data-tone="${tone}"
        data-vb-job-filter="${filterName}"
        aria-pressed="${active ? "true" : "false"}"
      >
        <span>${label}</span>
        <b class="vb-num">${count}</b>
      </button>
    `;
  }

  const pagingControls = totalJobPages > 1
    ? `
      <div class="vb-auto-pager">
        <button
          type="button"
          class="vb-page-button"
          data-vb-page-prev
          aria-label="Página anterior"
        >
          ‹
        </button>

        <div class="vb-page-status">
          <strong class="vb-num">
            ${currentJobPage + 1} / ${totalJobPages}
          </strong>

          <span>Troca automática em 10s</span>

          <i class="vb-rotation-track">
            <i class="vb-rotation-progress"></i>
          </i>
        </div>

        <button
          type="button"
          class="vb-page-button"
          data-vb-page-next
          aria-label="Próxima página"
        >
          ›
        </button>
      </div>
    `
    : `
      <div class="vb-auto-pager is-static">
        <div class="vb-page-status">
          <strong class="vb-num">1 / 1</strong>
          <span>todos os jobs deste filtro estão visíveis</span>
        </div>
      </div>
    `;

  jobsPanel.innerHTML = `
    <div class="vb-section-head vb-section-head--jobs">
      <div class="vb-section-title">
        <span class="vb-section-icon">
          ${iconSvg("list")}
        </span>

        <h2>JOBS DE BACKUP</h2>
      </div>
    </div>

    <div class="vb-section-menu vb-section-menu--jobs">
      <div class="vb-tabs">
        ${renderTab("with-data", "Com dados", withData, "cyan")}
        ${renderTab("success", "Sucesso", ok, "green")}
        ${renderTab("warning", "Aviso", warn, "amber")}
        ${renderTab("failed", "Falha", fail, "red")}
        ${renderTab("scheduled", "Agendados", scheduled, "cyan")}
        ${renderTab("unscheduled", "Sem agenda", unscheduled, "neutral")}
        ${renderTab("no-data", "Sem dados", none, "neutral")}
        ${renderTab("all", "Todos", total, "neutral")}
      </div>

      ${pagingControls}
    </div>

    <div class="vb-status-bar">
      <span
        class="is-ok"
        style="width:${total ? ok / total * 100 : 0}%"
      ></span>

      <span
        class="is-warn"
        style="width:${total ? warn / total * 100 : 0}%"
      ></span>

      <span
        class="is-fail"
        style="width:${total ? fail / total * 100 : 0}%"
      ></span>

      <span
        class="is-none"
        style="width:${total ? none / total * 100 : 0}%"
      ></span>
    </div>

    <div class="vb-job-table-head">
      <span>Status</span>
      <span>Job</span>
      <span>Próxima execução</span>
      <span>Última execução</span>
      <span>Resultado</span>
    </div>

    <div class="vb-jobs-page" data-vb-jobs-list></div>
  `;

  const jobsList = jobsPanel.querySelector(
    "[data-vb-jobs-list]"
  );

  if (!pagedJobs.length) {
    jobsList.innerHTML = `
      <div class="vb-empty">
        Nenhum job encontrado neste filtro.
      </div>
    `;
  } else {
    pagedJobs.forEach((job, index) => {
      const status = effectiveResult(job);
      const resultInfo = RESULT[status] || RESULT[3];
      const label = resultInfo[0];
      const className = resultInfo[1];
      const nextRun = fmtNextRun(job.nextRunTs);
      const translatedState = translateJobState(job.state);
      const stateClass = jobStateClass(job.state);

      jobsList.innerHTML += `
        <div
          class="vb-job-row"
          style="animation-delay:${index * 45}ms"
        >
          <span class="vb-status-dot d-${className}"></span>

          <div class="vb-job-name">
            <strong>${escapeHtml(job.name)}</strong>

            <small>
              ${escapeHtml(job.type || "Backup")}
              <i
                class="vb-job-state ${stateClass}"
                title="Estado atual retornado pela API"
              >
                ${escapeHtml(translatedState)}
              </i>
            </small>
          </div>

          <div class="vb-job-next is-${nextRun.tone}">
            <strong class="vb-num">
              ${escapeHtml(nextRun.main)}
            </strong>

            <small>
              ${escapeHtml(nextRun.detail)}
            </small>
          </div>

          <span class="vb-job-age vb-num">
            ${fmtAge(job.lastRunTs)}
          </span>

          <span class="vb-chip c-${className}">
            ${label}
          </span>
        </div>
      `;
    });
  }

  jobsPanel
    .querySelectorAll("[data-vb-job-filter]")
    .forEach((button) => {
      button.addEventListener("click", () => {
        root.dataset.vbJobFilter =
          button.getAttribute("data-vb-job-filter") ||
          "with-data";

        root.dataset.vbJobPage = "0";
        render(d);
      });
    });

  const previousPageButton = jobsPanel.querySelector(
    "[data-vb-page-prev]"
  );

  if (previousPageButton) {
    previousPageButton.addEventListener("click", () => {
      root.dataset.vbJobPage = String(
        (currentJobPage - 1 + totalJobPages) % totalJobPages
      );

      render(d);
    });
  }

  const nextPageButton = jobsPanel.querySelector(
    "[data-vb-page-next]"
  );

  if (nextPageButton) {
    nextPageButton.addEventListener("click", () => {
      root.dataset.vbJobPage = String(
        (currentJobPage + 1) % totalJobPages
      );

      render(d);
    });
  }

  /* REPOSITÓRIOS */

  const reposPanel = el(
    "section",
    "vb-panel vb-panel--repos"
  );

  const sortedRepos = repos
    .slice()
    .sort((repoA, repoB) => {
      const capacityA = Number(repoA.capacityBytes);
      const capacityB = Number(repoB.capacityBytes);

      const usageA = capacityA > 0
        ? 1 - Number(repoA.freeBytes) / capacityA
        : 0;

      const usageB = capacityB > 0
        ? 1 - Number(repoB.freeBytes) / capacityB
        : 0;

      return usageB - usageA;
    });

  const reposPerPage = Math.max(1, sortedRepos.length || 1);

  const totalRepoPages = 1;

  const currentRepoPage = 0;

  root.dataset.vbRepoPage = "0";

  const pagedRepos = sortedRepos;

  const repoPagingControls = `
    <div class="vb-repo-page-single">
      <strong class="vb-num">${repos.length}</strong>
      <span>REPOSITÓRIOS VISÍVEIS</span>
    </div>
  `;

  reposPanel.innerHTML = `
    <div class="vb-section-head vb-section-head--repos">
      <div class="vb-section-title">
        <span class="vb-section-icon">
          ${iconSvg("storage")}
        </span>

        <h2>REPOSITÓRIOS</h2>
      </div>

      ${repoPagingControls}
    </div>

    <div class="vb-repo-summary">
      <div>
        <span>Capacidade total</span>
        <strong class="vb-num">${fmtBytes(totalCapacity)}</strong>
      </div>

      <div>
        <span>Espaço livre</span>
        <strong class="vb-num">${fmtBytes(totalFree)}</strong>
      </div>
    </div>

    <div class="vb-repos-page" data-vb-repos-list></div>
  `;

  const reposList = reposPanel.querySelector(
    "[data-vb-repos-list]"
  );

  if (!pagedRepos.length) {
    reposList.innerHTML = `
      <div class="vb-empty">
        Nenhum repositório foi retornado pelas queries C e D.
      </div>
    `;
  } else {
    pagedRepos.forEach((repo, index) => {
      const capacity = Number(repo.capacityBytes);
      const free = Number(repo.freeBytes);

      const used = capacity > 0
        ? Math.max(0, capacity - free)
        : 0;

      const percentage = capacity > 0
        ? Math.max(
            0,
            Math.min(100, used / capacity * 100)
          )
        : 0;

      const tone =
        percentage >= 85
          ? "fail"
          : percentage >= 70
            ? "warn"
            : "ok";

      reposList.innerHTML += `
        <article
          class="vb-repo-card"
          style="animation-delay:${index * 55}ms"
        >
          <div class="vb-repo-top">
            <div>
              <strong>${escapeHtml(repo.name)}</strong>
              <span>${percentage.toFixed(0)}% utilizado</span>
            </div>

            <b class="vb-num">
              ${fmtBytes(free)} livre
            </b>
          </div>

          <div class="vb-repo-bar">
            <span
              class="is-${tone}"
              style="width:${percentage.toFixed(1)}%"
            ></span>
          </div>

          <div class="vb-repo-meta">
            <span>
              Usado
              <b class="vb-num">${fmtBytes(used)}</b>
            </span>

            <span>
              Total
              <b class="vb-num">${fmtBytes(capacity)}</b>
            </span>
          </div>
        </article>
      `;
    });
  }

  const previousRepoButton = reposPanel.querySelector(
    "[data-vb-repo-prev]"
  );

  if (previousRepoButton) {
    previousRepoButton.addEventListener("click", () => {
      root.dataset.vbRepoPage = String(
        (currentRepoPage - 1 + totalRepoPages) % totalRepoPages
      );

      render(d);
    });
  }

  const nextRepoButton = reposPanel.querySelector(
    "[data-vb-repo-next]"
  );

  if (nextRepoButton) {
    nextRepoButton.addEventListener("click", () => {
      root.dataset.vbRepoPage = String(
        (currentRepoPage + 1) % totalRepoPages
      );

      render(d);
    });
  }

  main.appendChild(jobsPanel);
  main.appendChild(reposPanel);

  root.appendChild(main);

  /* RODAPÉ */

  const footer = el("footer", "vb-footer");

  footer.innerHTML = `
    <div class="vb-collector-state ${
      collectorStale ? "is-stale" : "is-healthy"
    }">
      <span></span>

      ${
        collectorStale
          ? `Coletor sem dados recentes · Última coleta ${fmtAge(collector.lastRunTs)}`
          : `Coletor ativo · Última coleta ${fmtAge(collector.lastRunTs)} · Duração ${fmtCollectorDuration(collector.durationSec)}`
      }
    </div>

    <div class="vb-footer-counts">
      <span><i class="is-ok"></i>${ok} sucesso</span>
      <span><i class="is-warn"></i>${warn} aviso</span>
      <span><i class="is-fail"></i>${fail} falha</span>
      <span><i class="is-none"></i>${none} sem dados</span>
    </div>
  `;

  root.appendChild(footer);

  startClock();
  startDashboardRotation(
    d,
    totalJobPages,
    totalRepoPages
  );
}

/* =========================================================
   EXECUÇÃO COM DADOS REAIS
   ========================================================= */

try {
  if (!SERIES.length) {
    root.innerHTML = `
      <div
        style="
          padding:24px;
          border:1px solid rgba(224,161,6,.4);
          border-radius:13px;
          background:rgba(224,161,6,.12);
          color:var(--text);
          font-family:var(--font-sans);
        "
      >
        <strong style="color:var(--warn)">
          Nenhuma série chegou ao painel.
        </strong>

        <div style="margin-top:8px">
          Adicione as queries A até I no próprio HTML Graphics,
          marque todas como Instant e clique em Run queries.
        </div>
      </div>
    `;
  } else {
    const realData = buildRealData();

    console.log(
      "[Veeam Dashboard] Séries:",
      SERIES
    );

    console.log(
      "[Veeam Dashboard] Dados processados:",
      realData
    );

    render(realData);
  }
} catch (error) {
  console.error(
    "[Veeam Dashboard] Erro ao renderizar:",
    error
  );

  root.innerHTML = `
    <div
      style="
        padding:24px;
        border:1px solid rgba(240,82,76,.4);
        border-radius:13px;
        background:rgba(240,82,76,.12);
        color:var(--text);
        font-family:var(--font-sans);
      "
    >
      <strong style="color:var(--fail)">
        Erro ao renderizar o painel.
      </strong>

      <div style="margin-top:8px">
        ${escapeHtml(error && error.message ? error.message : String(error))}
      </div>
    </div>
  `;
}
